import scopeData from './mj-scope.json';
/**
 * Scope (範圍) of every structure: 摘要 (Summary) = named in the course summary the atlas must cover, 延伸 (Extended) = every other structure of the atlas.
 * The list is generated by scripts/audit-paokao.mjs into app/mj-scope.json (part ids of the matched structures and their pieces, plus normalised English names for
 * structures that have no atlas part: nerve, joint, brain and neck-vessel structures). A name counts for both sides (left and right are dropped).
 */
export type Scope = 'summary' | 'extended';
export const SCOPE_LABEL: Record<Scope, [string, string]> = {summary: ['Summary', '摘要'], extended: ['Extended', '延伸']};
const IDS = new Set<string>(scopeData.ids), NAMES = new Set<string>(scopeData.names);
export const scopeName = (s: string) => s.toLowerCase().replace(/\.[lr](\.\d+)?$/, '').replace(/\.\d+$/, '').replace(/\b(left|right)\b/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
/** Scope of one structure: by the id of any of its parts, then by its English name. */
export function scopeOf(name: string, ids: readonly string[] = []): Scope {
  if (ids.some(id => IDS.has(id)) || NAMES.has(scopeName(name))) return 'summary';
  return 'extended';
}
